Function message <- StockFromLine(line As String)
  Define message As String;
  Switch indexOf(line, ";") Do
    Some(cut):
      message <- substring(line, 0, cut - 1) + " has " + substring(line, cut + 1, length(line) - 1);
    None: message <- "Invalid line";
  EndSwitch
EndFunction

Algorithm ReadLine
  Define line As String;
  Read line;
  Write StockFromLine(line);
EndAlgorithm
